import "pe"

rule MAL_CredentialStealer_RedLine_ConfirmedSampleSet
{
    meta:
        description = "Detects confirmed credential-stealer samples matching analyst-extracted RedLine indicators"
        author = "SOC Detection Engineering"
        date = "2026-07-31"
        scope = "Confirmed sample set only; not a general RedLine family attribution"
        confidence = "high"
        reference = "Internal malware analysis"
        hash = "<INSERT_CONFIRMED_SAMPLE_SHA256>"

    strings:
        // APIs associated with DPAPI credential decryption and SQLite database access.
        $api_crypt_unprotect = "CryptUnprotectData" ascii wide
        $api_sqlite_open     = "sqlite3_open" ascii wide

    condition:
        // Require a valid PE containing both analyst-extracted API indicators.
        pe.is_pe and
        all of ($api_*) and

        // Require both expected PE sections, without depending on section order.
        for any i in (0 .. pe.number_of_sections - 1) : (
            pe.sections[i].name == ".text"
        ) and
        for any i in (0 .. pe.number_of_sections - 1) : (
            pe.sections[i].name == ".rdata"
        )
}
```

