import "pe"

/*
    Sample-scoped detection for analyst-confirmed RedLine credential-stealer
    samples. This rule does not assert that every matching file belongs to
    the RedLine family. Validate new matches before expanding attribution.
*/
rule SOC_Credential_Stealer_RedLine_Confirmed_Sample_Set
{
    meta:
        description       = "Detects the confirmed RedLine sample set using analyst-extracted PE and API indicators"
        author            = "SOC Detection Engineering"
        date              = "2026-07-31"
        scope             = "Confirmed sample set only"
        attribution       = "No family-wide attribution intended"
        confidence        = "High for the confirmed sample set; unknown for unrelated samples"
        reference         = "Internal malware analysis"
        sample_sha256     = "REPLACE_WITH_CONFIRMED_SAMPLE_SHA256"

    strings:
        // Windows DPAPI function commonly used to decrypt stored credentials.
        $api_crypt_unprotect = "CryptUnprotectData" ascii

        // SQLite function consistent with opening browser credential databases.
        $api_sqlite_open = "sqlite3_open" ascii

    condition:
        // Require a PE file rather than matching these API names in arbitrary data.
        uint16(0) == 0x5A4D and
        pe.number_of_sections > 0 and

        // Both analyst-extracted API indicators must be present.
        all of ($api_*) and

        // Require the section layout observed in the confirmed samples.
        for any i in (0..pe.number_of_sections - 1) : (
            pe.sections[i].name == ".text"
        ) and
        for any i in (0..pe.number_of_sections - 1) : (
            pe.sections[i].name == ".rdata"
        )
}
